INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима: Истинодории масофаи тармоки нӯри бағол</h2>\n<p>Дар солҳои охир, обёрӣи қатрагӣ ва ба таври махсус системҳои оиннокунанда <strong>тармоки нӯри</strong> ба яке аз усулҳои асосии таъмини об барои киштҳои дона ва бағолҳо дар минтақаҳои камоб табдил ёфтааст. Бағол, бо сабаби ниёз миёна ба об ва ҳассосияти решаҳои он ба обгирӣ, аз киштҳое мебошад, ки бо истифода аз тармоки нӯри метавонад бартарии баландтар нисбат ба обёрӣи хокишӣ нишон диҳад. Аммо саволи асосӣ, ки ҳар як деҳқон бо он рӯ ба рӯ мешавад, муайян кардани <strong>масофаи тармоки нӯри бағол</strong> мусоид мебошад. Ин масофа на танҳо як рақами собит аст, балки метаварзе аст, ки мувофиқи амиқии реша, намуди хок, сароғозии баромади қатракунон ва ҷобаҷогузории сафҳои кишт муайян карда мешавад.</p>\n<p>Муайян кардани нодурусти масофа метавонад ба ду мушкилоти бузург оварда расонад: ё қисми васеи хоки атрофи байни сафҳо хушк бимонад ва решаҳои тарафӣ парёз нашаванд, ё рутубати зиёд боиси вайроншавии реша ва афзоиши зиёди отҳаҳо дар масофаи сафҳо гардад. Дар ин мақола, мо ба таҳқиқи меъёрҳои тавсияшуда барои ҷобаҷогузории сафҳо ва масофаи тармоки нӯри дар саҳроҳои бағол мепардозем.</p>\n\n\n\n<h2>Осноҳои умумии масофаи тармоки нӯри дар ҷобаҷогузории сафҳои бағол</h2>\n<p>Барои дарки дурусти фосилаи ришаи нӯри (типи), аввал бояд сохтори решаҳои боборо (баққа) дар назар дошт. Решаҳои боборо одданан то чуқурии 30 то 45 сантиметр фаъоланд ва паҳншавии тарафи он, вобаста ба хок, аз 20 то 50 сантиметр аз ҷои кӯфтӣ (нахӯл) фарқ мекунад. Бинобар ин, мақсади обёркунӣ тавассути нӯри (типи) ин аст, ки минтақаи тар биҳамо дар атрофи чуққорҳо (дропнерҳо) метавонад решаҳои боборо-ро пӯшад, бе он ки бо нӯри (типи) сатри (риштаи) ҳамсоя таъсири лозиманашадора дошта бошад.</p>\n<h3>Таъсири намуди хок ба интихоби фосила</h3>\n<ul>\n<li><strong>Хокҳои румолӣ (ранг) ва сабуки:</strong> Фаромадани рӯйхати об баланд аст ва паҳншавии тарафии таробӣ (шуробӣ) камтар аст. Дар шароити чунин, фосилаи нӯри (типи) боборо бояд камтар бошад, то таробӣ (шуробӣ) дар сатҳ нигоҳ дошта шавад ва ба сӯи реша ҳаракат кунад. Одатан нӯри (типи) ҳамчун як нӯри (типи) (Single-line) дар маркази сатр (ришта) ё ду нӯри (типи) муқоисагари симметрӣ бо фосилаи 15 то 20 сантиметр аз ҷои кӯфтӣ (нахӯл) истифода мегирад.</li>\n<li><strong>Хокҳои лумӣ ва луми сабук:</strong> Мутобиқати хуби байни фаромадан ва паҳншавии тарафии таробӣ (шуробӣ) вуҷуд дорад. Фосилаи нӯри (типи) метавонад каме зиёдтар бошад. Барои синфи кӯфтӣ (нахӯл) боборо бо андозаи 60 то 90 сантиметр, истифодаи нӯри (типи) дар фосилаи 30 то 40 сантиметр аз хати кӯфтӣ (нахӯл) меъёри тиллоӣ ҳисоб мешавад.</li>\n<li><strong>Хокҳои вазнини лумӣ ва ғализ:</strong> Фаромадани об хеле дилер аст ва хатари талло (обғарқ) мавҷуд аст. Дар ҳолати чунин, истифодаи чуққорҳо (дропнерҳо) бо даъбеи пасттар ва фосилаи бештар байни нӯри (типи) муқоисагар лозим аст, то таробӣ (шуробӣ) захира нагарданд.</li>\n</ul>\n<p>Бояд дар назар дошта бошед, ки масофаи лентаи капель бақла набояд аз нимаи паҳии минтақаи зери реша калонтар бошад. Яъне, агар паҳии сафи ҷусуроти бақла 90 сантиметр бошад, масофа байни лентаи капельи як сатр ва лентаи сатри қариб набояд аз 45 сантиметр зиёд бошад, магар он ки сраъи омадани об аз капель (дби) хеле паст бошад.</p>\n\n<h2>Муайян кардани масофаи лентаи капель аз рӯи сраъи омадани об (дби)</h2>\n<p>Яке аз параметрҳои асосӣ, ки аксар вақт дар ҳисоб кардани масофаи лентаи капель бақла ба назар гирифта намешавад, сраъи омадани об (Flow Rate) аст. Байни сраъи омадани об ва масофаи мувофиқ робитаи мустақим мавҷуд аст:</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-باقلا-استانداردهای-توصیهشده-تصویر-شاخص.webp" alt="فاصله نوار تیپ در کشت باقلا: استانداردهای توصیه‌شده - تصویر 1"/><figcaption>masofai lenta chodakhoи layout сатри ҷусурот baqla</figcaption></figure>\n<h3>Муайян кардани амалии масофа</h3>\n<p>Чун қонуни оддӣ, масофаи иҷозатшуда байни лентаҳои капель симетрикӣ дар як сатр ё масофа байни сатрҳое, ки лентаи капель доранд, бо камшавии сраъи омадани об кам мешавад. Барои мисол, агар аз системаи капель бо сраъи 2 литр дар соат истифода баред, доираи намудашуда хурдтар аст ва масофаи лентаи капель бақла тақрибан 30 то 40 сантиметр будан лозим аст. Аммо агар сраъи омадани об 4 литр дар соат бошад, паҳши намнокӣ зиёдтар аст ва метавон масофаро то 50-60 сантиметр зиёд кард.</p>\n<p>Барои ҳисоб кӯшиши дақиқтар, метавон аз мафҳумҳои марбут ба тақсимоти об ва вақти обёрӣ истифода бурд. Масофаи лентаи капель бояд чунин танзим карда шавад, ки вақти зарурӣ барои расидан ба намҳои хоҳишидаи реша аз як даври обёрии стандартӣ зиёд набошад.</p>\n\n\n\n<h2>Мутобиқ кардани масофаи лентаи капель бақла бо шароити иқлимӣ ва минтақавӣ</h2>\n<p>Фосили риби лубиёнӣ дар тамоми кишвар як параметри доимӣ нест. Дар минтаҳаҳои гарм ва хушк бо таҳомми баланд, намии мавҷуда дар хок тезтар фарида меравад. Дар ин минтаҳаҳо, ҷобаҷогузории сатҳҳои лубиёнӣ бояд чунин бошад, ки дар охирин фасли офшакӣ сояи иҷозатӣ вуҷуд дошта бошад. Ин талаботи фосили камтар байни сатҳҳо ва дар натиҷа фосили наздиктари риби лубиёнӣ дорад.</p>\n<p>Дар муқобил, дар минтаҳаҳои намноктар, метавон аз сатҳҳои васеътар истифода бурд. Дар чунин шартҳо, санҷиши намунавии системаи риби лубиёнӣ дар замин пеш аз кабудони асосӣ, муҳимии дучанд пайдо мекунад, то аз шикастани система ба сабаби пуршудагии хок пешгирӣ шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-باقلا-استانداردهای-توصیهشده-کاربرد-عملی.webp" alt="فاصله نوار تیپ در کشت باقلا: استانداردهای توصیه‌شده - تصویر 2"/><figcaption>дrip tape spacing row layout crop лубиён</figcaption></figure>\n<p>Инчунин, шудоии замин низ ба ҷобаҷогузорӣ таъсир мерасонад. Дар шудоии тез, ҷараёни об дар риби лубиёнӣ суръат мегирад ва метавонад об ба тарафи поёнтар бештар ҳаракат кунад. Дар ин ҳолат, фосили риби лубиёнӣ дар оғози шудоӣ бояд камтар ва дар анҷоми шудоӣ танзимшаванда бошад, ё аз тамғагӣ бо деби пайваста истифода шуда шавад, то тақсимоти якхела ба вуҷуд орад.</p>\n\n<h2>Нуктаҳои амалӣ барои беҳтар кардани фосили риби лубиёнӣ дар заминҳои лубиёнӣ</h2>\n<p>Иҷрои дурусти системаи риби лубиёнӣ талаботи диққат ба тафсилоти иҷроранҷ дорад. Дар поён нуқтаеро пешниҳод мекунем, ки метавонад ба деҳқонон кӯмак кунад, то фосили риби лубиёниро беҳтар кунанд:</p>\n<ol>\n<li><strong>Ченкунии дақиқи ҷойи гирифтан:</strong> Фосили риби лубиёнӣ ҳамеша аз маркази ҷойи гирифтан (ва на аз канори тоб) чен карда шавад. Одатан, фосили 20 то 30 сантимер аз хати кабудонуи нуқтаи оғози риби лубиёнӣ хуб аст.</li>\n<li><strong>Диққати ҷиҳати боди доминант:</strong> Агар боди доминант аз як тараф бошад, баробар будани масофаи нӯри қатори фасолоидҳо метавонад сабабгард, ки як тарафшаклҳои шикола хушкшаванда бошад. Дар ин ҳолатҳо, метавон ҷойгиркунии занҷирӣ (Series)-ро ба ҷои ҷойгиркунии муқобил истифода бурд.</li>\n<li><strong>Қатъи иловагӣ ва чархӯбҳо:</strong> Дар фосилаҳои калони нӯри қаторҳо, миқдори зиёди чархӯбҳо байни қаторҳо мерӯянд. Барои ҳалли ин масъала, бе кам кардани масофаи нӯри қатори фасолоидҳо, метавон истифодаи якчанд қаторӣ (Multi-row)ро анҷом дод, то тозагии камтари фазоро эҷод кунад.</li>\n<li><strong>Ҳисси муҳаккамон:</strong> Барои муайян кардани дақиқтари зарурати об, метавон ба мақолаҳо монанди миқдори истифодаи об дар гуногуни корҳои кишоварзӣ ва муқоисаи он бо зарурати фасолоидҳо муроҷиат кард. Ҳар қадар дақиқии зиёди ҳисобкунии ETc (буғорзӣ-ташъиғ) вуҷуд дошта бошад, масофаи нӯри қатори фасолоидҳо дақиқтар интихоб мешавад.</li>\n<li><strong>Назорати тарии хок:</strong> Истифодаи сенсорҳои тарии хок дар фосилаҳои гуногун аз нӯри қатор, беҳтарин роҳ барои дарки воқеии сарфаи система аст. Агар масофаи нӯри қатори фасолоидҳо зиёд бошад, тарии минтақаи миёна байни қаторҳо ба сифр мерасад.</li>\n</ol>\n\n\n\n<h2>Саволҳои пурравоҷ (FAQ) дар бораи фосилаи шитоби каҳову барқалам</h2>\n<h3>1. Оё имкон дорад, ки дар ҳар як қатори барқалам ду шитоб истифода шавад?</h3>\n<p>Бале, истифодаи ду шитоби симметрӣ дар қаторҳои васеъ (аз 70 сантиметр зиёд) тавсия дода мешавад. Ин кор боиси он мегардад, ки минтаҳаи решаҳо ба таври якхела намнокӣ пайдо намоянд. Фосилаи ҳар як шитоб бояд ҳадди ақал 15 то 20 сантиметр аз хати марказии ғирорӣ (кашш) бошад. Агар аз ду шитоб истифода баред, анҷури умумии таҳинҳо бояд тақсим шавад, то намӣ зиёдатӣ ҷамъ нашавад.</p>\n<h3>2. Чӣ тавр метавонам фаҳмам, ки фосилаи шитоби барқалам ман мувофиқ аст?</h3>\n<p>Беҳтарин усул, кафши амиқ (тақрибан 20 то 30 сантиметр) дар нуқтаҳои гуногуни қатор, ба таъсис дар фосилаи байни шитобҳои барӯбар аст. Аگر хок тоза ва хушк бошад, фосилаи шитоби барқалам зиёд аст. Агар хок часпак ва хеле намнок бошад, фосила кам аст. Хок бо рангу данданаи якхела нишондиҳандаи мувозинати мувофиқ аст. Инчунин метавонед аз маълумотҳои муфассал қисмҳои системаи шитоб барои хатоёбии оқим истифода баред.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-باقلا-استانداردهای-توصیهشده-جزئیات-فنی.webp" alt="فاصله نوار تیپ در کشت باقلا: استانداردهای توصیه‌شده - تصویر 3"/><figcaption>drip tape spacing row layout crop барқалам</figcaption></figure>\n<h3>3. Оё фосилаи шитоби барқалам ба харҷи кшт таъсир мерасонад?</h3>\n<p>Бале, зиёд шудани фосилаи шитоб ба маънои кам шудани сарфаи умумии об аст, аммо агар фосила зиёдатӣ зиёд шавад, паст шудани ҳосилнокии дон ҷуброннопадӣ хоҳад буд. беҳтар кардани фосилаи шитоби барқалам мувозинат байни харҷи об ва самаранокии растани аст. ҳисобкунии дақиқтарро метавон тавассути мақолаҳои вобаста ба миқдори тахминии истифодаи об ва муқоисаи он бо самаранокии иқтисодӣ иҷро кард.</p>\n\n<h2>Хулоса: Бартарин барориши фосилаи риши кунҷи ҷунги барои оянда</h2>\n<p>Муайян кардани фосилаи риши кунҷи ҷунги илми дақиқ нест, балки ҷамъбасти донишҳои хокшиносӣ, гидролик ва кишоварзӣ аст. Калити ғолим дар ин аст, ки ба ҷойи истифодаи як рақами собит барои тамоми майдонҳо, ҳар як майдонро вобаста ба намуди хок, дебити қотрпашҳо ва шароитҳои иқлимӣ шахсӣ кардан лозим аст. Ташкили сафҳои ҷунги бояд ба таври чунин тарҳбандӣ кунҷи ҷунги, ки риши пурраи фарогирии решаҳоро таъмин мекунад, муайян шавад.</p>\n<p>Ба деҳқонон тавсия мешавад, ки пеш аз насби риши кунҷи як тест саҳроӣ бо фосилаҳои гуногун (масалан, 20, 30 ва 40 сантиметр) иҷро кунанд ва рушди бутта ва таркии хокиро дар назорат доранд. Ин усули сода хароҷоти хатогиҳо ва тағйиротҳо дар тамоми фаврони коҳиш медиҳад. Дар охир, интихоби дақиқ дар ҳисоб кардани ниёз ба об ва таркиб додани он бо фосилаи дурусти риши кунҷи ба зиёдшавии босирати ҷунги ва кам шудани истифодаи об оварда мерасонад. Бо амали саривақти ин нуқтаҳо, деҳониҳои ҷунги метавонанд ба истеҳсои устувор ва иқтисодӣ даст пайванд.</p>\n<p><strong>Мавзӯъҳои алоқаманд:</strong> <a href="https://navar-abyari.ir/miqdori-tuxmi-javori-donador-dar-yak-gektar/">miqdori tuxmi javori donador dar yak gektar</a>， <a href="https://navar-abyari.ir/%D8%B9%D9%85%D9%84%DA%A9%D8%B1%D8%AF-%D9%BE%DB%8C%D8%A7%D8%B2-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">D8B9D985D984DAA9D8B1D8AF D9BEDB8CD8A7D8B2 D8AFD8B1 D987DAA9D8AAD8A7D8B1</a>， <a href="https://navar-abyari.ir/%D9%86%DA%AF%D9%87%D8%AF%D8%A7%D8%B1%DB%8C-%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE-%D9%88-%D9%87%D8%B2%DB%8C%D9%86%D9%87/">D986DAAFD987D8AFD8A7D8B1DB8C D986D988D8A7D8B1 D8AADB8CD9BE D988 D987D8B2DB8CD986D987</a>， <a href="https://navar-abyari.ir/drip-tape-melon-irrigation-guide-tajikistan/">drip tape melon irrigation guide tajikistan</a></p>','Фавраи банди нон барои парвариши нон: тавсияи муқаррарӣ','Ашноӣ бо принсипҳои муайян кардани масофаи лентавии даръеб дар кишмечҳои нохӯрӣ, таъсири он ба ҳосилдорӣ ва усулҳои амалӣ барои беҳтарсозии системаи обёркунии қатрагӣ.','publish','closed','closed','favro-i-bandi-non-baro-parvarish-i-non',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
